body.script:
function rafraichir(){
  fetch('/tour/atelier-malo/data',{headers:{'Accept':'application/json'}})
    .then(function(r){return r.json();})
    .then(function(data){
      var box=document.getElementById('liste');
      box.innerHTML='';
      data.forEach(function(d){
        var el=document.createElement('div'); el.className='demande';
        var h=document.createElement('h3'); h.textContent=d.name;
        var s=document.createElement('span'); s.className='etat '+d.etat; s.textContent=d.etat;
        h.appendChild(s);
        var note=document.createElement('p'); note.className='note'; note.textContent=d.date;
        var cons=document.createElement('p'); cons.textContent=d.consigne;
        el.appendChild(h); el.appendChild(note); el.appendChild(cons);
        if(d.reponse){
          var pre=document.createElement('pre'); pre.textContent=d.reponse; el.appendChild(pre);
        } else {
          var p=document.createElement('p'); p.className='note'; p.textContent='En attente...';
          el.appendChild(p);
        }
        box.appendChild(el);
      });
    });
}
fetch('/tour/atelier-malo/taches',{headers:{'Accept':'application/json'}})
  .then(function(r){return r.json();})
  .then(function(data){
    var sel=document.getElementById('select_tache');
    data.forEach(function(t){
      var o=document.createElement('option');
      o.value=t.id;
      o.textContent=t.name+' ('+t.projet+')';
      sel.appendChild(o);
    });
  });
rafraichir();
setInterval(rafraichir, 20000);
